import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易要義卷二 * 上","description":"周易要義 - 周易要義卷二 * 上","frontmatter":{"title":"周易要義卷二 * 上","description":"周易要義 - 周易要義卷二 * 上"},"headers":[],"relativePath":"classics/yaoyi/005.md","filePath":"classics/yaoyi/005.md"}'),r={name:"classics/yaoyi/005.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要義卷二-上" tabindex="-1">周易要義卷二 * 上 <a class="header-anchor" href="#周易要義卷二-上" aria-label="Permalink to “周易要義卷二 * 上”">​</a></h1><p>欽定四庫全書</p><p>宋魏了翁輯泰至謙</p><p>䷊</p><p>乾下坤上 泰：小往大來，吉，亨。正義曰：「小往大來，吉亨」者，陰去故「小往」，陽長故「大來」，以此吉而亨通。此卦亨通之極，而四德不具者，物既泰通，多失其節，故不得以為元始而利貞也。所以象雲「財成輔相」，故四德不具。泰，如字。大通也，鄭雲：「通也。」馬雲：「大也。」坤宮三世卦</p><p>象曰：天地交，泰。後以財成天地之道，輔相天地之宜，以左右民。「泰」者，物大通之時也。上下大通，則物失其節，故財成而輔相，以左右民也。「天地之道」者，謂四時也。冬寒夏暑、春生秋殺之道，若氣相交通，則物失其節。物失其節，則冬溫夏寒，秋生春殺。君當財節成就，使寒暑得其常，生殺依其節。此天地自然之氣，故云「天地之道」也。「天地之宜」者，謂天地所生之物，各有其宜。若大司徒雲「其動物植物」，及職方雲揚州其貢宜稻麥，雍州其貢宜黍稷。若天氣大同，則所宜相反，故人君輔助天地所宜之物，各安其性，得其宜。</p><p>九三，無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福。乾本上也，坤本下也，而得泰者，降與升也。而三處天地之際，將復其所處。復其所處，則上守其尊，下守其卑，是故無往而不復也，無平而不陂也。處天地之將閉，平路之將陂，時將大變，世將大草，而居不失其正，動不失其應，艱而能貞，不失其義，故「無咎」也。信義誠著，故不恤其孚而自明也，故曰「勿恤其孚，於食有福」也。陂，彼偽反，徐甫寄反，傾也，注同；又破河反，偏也。象曰：「無往不復」，天地際也。天地將各分復之際，</p><p>六四，翩翩，不富以其鄰，不戒以孚。乾樂上覆，坤樂下復，四處坤首，不固所居，見命則退，故曰「翩翩」也。坤爻皆樂下，己退則從，故不待富而用其鄰也。莫不與己同其志願，故不待戒而自孚也。象曰：「翩翩不富」，皆失實也。「不戒以孚」，中心願也。正義曰：「六四，翩翩」者，四主坤首，而欲下復，見命則退，故翩翩而下。象曰「皆失實」者，解「翩翩不富」之義。由眾陰皆失其本實所居之處，今既見命，翩翩樂動，不待財富，並悉從之，故云「皆失實」也。「不戒以孚，中心願」者，解「不戒以孚」之義。所以不待六四之戒告，而六五、上六皆已孚信者，由中心皆願下復，故不待戒而自孚也。</p><p>六五，帝乙歸妹，以祉元吉。婦人謂嫁曰「歸」。泰者，陰陽交通之時也。女處尊位，履中居順，降身應二，感以相與，用中行願，不失其禮。「帝乙歸妹」，誠合斯義。履順居中，行願以祉，盡夫陰陽交配之宜，故「元吉」也。祉，音恥，一音勑子反，又音止。</p><p>上六，城復於隍，勿用師。自邑告命，貞吝。居泰上極，各反所應。泰道將滅，上下不交，卑不上承，尊不下施，是故「城復於隍」，卑道崩也。「勿用師」，不煩攻也。「自邑告命，貞吝」，否道已成，命不行也。隍，音皇，城塹也。子夏作「堭」，姚作「湟」。正義曰：子夏傳雲：隍是城下池也。城之為體，由基土培扶，乃得為城。今下不培扶，則損壞，以此崩倒，反覆於隍。猶君之為體，由臣之輔翼。今上下不交，臣不扶君，君道傾危。</p><p>䷋</p><p>坤下乾上 否之匪人，不利君子貞，大往小來。疏：「否之」至「小來」。正義曰：「否之匪人」者，言否閉之世，非是人道交通之時，故云「匪人」。不利君子貞者，由小人道長，君子道消，故不利君子為正也。陽氣往而陰氣來，故云「大往小來」。陽主生息，故稱大。陰主消耗，故稱小。否，備鄙反，卦內同，閉也，塞也。乾宮三世卦</p><p>初六，拔茅茹以其匯，貞吉，亨。居否之初，處順之始，為類之首者也。順非健也，何可以徵？居否之時，動則入邪，三陰同道，皆不可進，故「茅茹」以類，貞而不諂，則「吉亨」。邪，似嗟反。諂，勑檢反。象曰：「拔茅貞吉」，志在君也。志在於君，故不苟進。</p><p>六二，「包承」至亂群也。正義曰：「包承」者，居否之世而得其位，用其至順，包承於上。「小人吉」者，否閉之時，小人路通，故於小人為吉也。「大人否，亨」者，若大人用此包承之德，能否閉小人之吉，其道乃「亨」。象曰「大人否，亨，不亂群」者，此釋所以「大人否，亨」之意。良由否閉小人，防之以得其道，小人雖盛，不敢亂群。</p><p>䷌</p><p>離下乾上 同人於野，亨。利涉大川，利君子貞。正義曰：同人謂和同於人。「於野，亨」者，野是廣遠之處，借其野名，喻其廣遠。言和同於人，必須寬廣，無所不同，用心無私，處非近狹，遠至於野，乃得亨通，故云「同人於野，亨」。與人同心，足以涉難，故曰「利涉大川」也。與人和同，易涉邪僻，故「利君子貞」也。此「利涉大川」，假物象以明人事。同人，和同也。離宮歸魂卦</p><p>同人。曰「同人於野，亨，利涉大川，乾行也」。所以乃得「同人於野，亨，利涉大川」，非二之所能也，是乾之所行，故特曰「同人曰」。</p><p>象曰：「天與」至「辨物」。正義曰：天體在上，火又炎上，取其性同，故云「天與火」。同人。「君子以類族辨物」者，族，聚者也。言君子法此「同人」，以類而聚也。「辨物」謂分辨事物，各同其黨，使自相同，不間雜也。辨如字，王肅卜免反。</p><p>初九，「同人於門」至誰咎也。正義曰：「同人於門」者，居同人之首，無應於上，心無系吝，含弘光大，和同於人，在於門外，出門皆同，故云「無咎」也。象曰「又誰咎」者，釋「出門同人無咎」之義。言既心無系吝，出門逢人皆同，則誰與為過咎。</p><p>上九，同人於郊，無悔。郊者，外之極也。處「同人」之時，最在於外，不𫉬同志，而遠於內爭，故雖無悔吝，亦未得其志。遠，袁萬反。爭，爭鬥之爭。象曰：「同人於郊」，志未得也。凡處同人而不泰焉，則必用師矣。不能大通，則各私其黨而求利焉。楚人亡弓，不能忘楚，愛國愈甚，益為他災，是以同人不弘。剛健之爻，皆至用師也。正義曰：「凡處同人而不泰焉，則必用師矣」者，王氏注意非止上九一爻，乃總論同人一卦之義。去初、上而言，二有同宗之吝，三有「伏戎」之禍，四有不克之困，五有「大師」之患，是處「同人」之世，無大通之志，則必用師矣。「楚人亡弓，不能忘楚，愛國愈甚，益為他災」者，案：孔子家語弟子好生篇雲：「楚昭王出遊，亡烏號之弓。左右請求之。王曰：楚人亡弓，楚人得之，又何求焉？孔子聞之曰：惜乎，其志不大也。不曰人亡弓，人得之，何必楚也？」昭王名軫。哀六年，吳伐陳，楚救陳，在城父卒。此愛國而致他災也。引此者，證同人不弘皆至用師矣。</p><p>䷍</p><p>乾下離上 大有：元亨。不大通，何由得「大有」乎？「大有」則必元亨矣。正義曰：「大有，元亨」者，柔得尊位，群陽並應，能大所有，故稱「大有」。既能「大有」，則其物大得亨通，故云「大有，元亨」。大有，包容豐富之象。乾宮歸魂卦</p><p>象曰：火在天上，「大有」。君子以遏惡揚善，順天休命。大有，包容之象，故遏惡揚善，成物之性。「順天休命」，順物之命。正義曰：不雲天在火下而云「火在天上」者，天體高明，火性炎上，是照耀之物，而在於天上，是光明之甚，無所不照，亦是包含之義，又為揚善之理也。</p><p>九三公用亨於天子小人弗克處大有之時居下體之極，乘剛健之上，而履得其位，與五同功，威權之盛，莫此過焉。公用斯位，乃得通乎天子之道也。小人不克，害可待也。亨，許庚反，通也。下同。眾家並香兩反。京雲：「獻也。」於雲：「享宴也。」姚雲：「享，祀也。」</p><p>九四：「匪其彭，無咎。」既失其位，而上近至尊之威，下比分權之臣，其為懼也可謂危矣。惟夫有聖知者，乃能免斯咎也。三雖至盛，五不可舍，能辨斯數，專心承五，常匪其旁，則「無咎」矣。旁，謂三也。彭，步郎反，子夏傳作「旁」。於雲：「彭亨，驕滿貌。」王肅雲：「壯也。」虞作𡯁。姚雲：「彭、旁，俗音同。」</p><p>䷎</p><p>艮下坤上 「謙」：亨，君子有終。正義曰：「謙」者，屈躬下物，先人後己，以此待物，則所在皆通，故曰「亨」也。小人行謙，則不能長久，唯「君子有終」也。謙必獲吉，其吉可知，故不言之。凡易經之體，有吉理可知而不言「吉」者，即此謙卦之繇，及乾之九五「利見大人」，是吉理分明，故不雲「吉」也。若坤之六五及泰之六五，並以陰居尊位，若不行此事則無吉，若行此事則得其吉，故並稱「元吉」。其餘皆言「吉事」，亦仿此。亦有大人為吉，於小人為兇，若否之九五雲「休否，大人吉」是也。或有於小人為吉，大人為兇，若屯之九五「小貞吉，大貞兇」及否之六二「包承，小人吉」之類是也。亦有其吉灼然而稱「吉」者，若大有上九「自天祐之，吉，無不利」之類是也。但易之為體，不可以一為例，今各隨文解之，義具諸卦之下。今謙卦之繇，其吉可知也。既不雲「吉」，何故初六、六二及九三並雲「吉」者？謙卦是總諸六爻，其善既大，故不須雲「吉」也。六爻各明其義，其義有優劣，其德既小，嫌其不吉，故須「吉」以明之也。謙卑退為義，屈己下物也。兌宮五世卦，子夏作「銜」，雲：銜，謙也。</p><p>彖曰：「謙亨」至之終也正義曰：「謙，亨。天道下濟而光明，地道卑而上行」者，此釋「亨」義也。欲明天地上下交通，「坤」體在上，故言「地道卑而上行」也。其地道既上行，天地相對，則「天道下濟」也。且「艮」為陽卦，又為山，天之高明，今在下體，亦是「天道下濟」之義也。「下濟」者，謂降下濟生萬物也。而「光明」者，謂三光垂耀而顯明也。「地道卑而上行」者，地體卑柔而氣上行，交通於天，以生萬物也。「天道虧盈而益謙」者，從此以下，廣說謙德之美，以結君子能終之義也。「虧」謂減損，減損盈滿而增益謙退。若日中則昃，月盈則食，是虧減其盈。盈者虧減，則謙者受益也。「地道變盈而流謙」者，丘陵川穀之屬，高者漸下，下者益高，是改變「盈」者，流佈「謙」者也。「鬼神害盈而福謙」者，驕盈者被害，謙退者受福，是「害盈而福謙」也。「人道惡盈而好謙」者，盈溢驕慢者皆以惡之，謙退恭巽悉皆好之。「謙尊而光，卑而不可逾」者，尊者有謙而更光明盛大，卑謙而不可逾越，是君子之所終也。言君子能終其謙之善事，又𫉬謙之終福，故云「君子之終」也。</p><p>象曰：地中有山，謙。君子以裒多益寡，稱物平施。多者用謙以為裒，少者用謙以為益，隨物而與，施不失平也。正義曰：「裒多」者，君子若能用此謙道，則裒益其多。言多者得謙，物更裒聚，彌益多也，故云「裒多」即謙尊而光也，是尊者得謙而光大也。「益寡」者，謂寡者得謙而更進益，即卑而不可逾也，是卑者得謙而更增益，不可逾越也。「稱物平施」者，稱此物之多少，均平而施。</p><p>上六，鳴謙，利用行師，徵邑國。最處於外，不與內政，故有鳴而已，志功未得也。處外而履謙順，可以「徵邑國」而已。徵邑國，本或作「徵國邑」者，非。象曰：「鳴謙」，志未得也。可用行師，「徵邑國」也。夫吉凶悔吝，生乎動者也。動之所起，興於利者也。故飲食必有訟，訟必有眾起。未有居眾人之所惡，而為動者所害；處不競之地而為爭者所奪。是以六爻雖有失位、無應、乘剛，而皆無兇咎悔吝者，以謙為主也。「謙尊而光，卑而不可逾」，信矣哉！周易要義卷二上，</p>',30)])])}const f=a(r,[["render",i]]);export{m as __pageData,f as default};
